insert into field_task (id, asset_id, block_window_id, title, title_hi, hypothesis, hypothesis_hi, falsifier, falsifier_hi, service_date, starts_at, ends_at, level, status) values ('task-12t', 'ADRA/TC/12T', 'RB-28', 'Inspect ballast and cess drain', 'बैलास्ट और नाली की जाँच', 'Wet, fouled ballast is lowering ballast resistance (F1).', 'गीला, गंदा बैलास्ट बैलास्ट प्रतिरोध घटा रहा है (F1)।', 'If cable insulation is below 0.5 MΩ, record it — the cause is likely the joint (F2), not F1.', 'यदि केबल इंसुलेशन 0.5 MΩ से कम है, तो दर्ज करें — कारण जोड़ (F2) हो सकता है, F1 नहीं।', '2026-07-16'::date, '02:10'::time, '03:40'::time, 'watch'::alert_level, 'planned'::task_status) on conflict (id) do update set title = excluded.title, status = excluded.status;
insert into field_task (id, asset_id, block_window_id, title, title_hi, hypothesis, hypothesis_hi, falsifier, falsifier_hi, service_date, starts_at, ends_at, level, status) values ('task-14t', 'ADRA/TC/14T', 'RB-29', 'Rod cess drain, Down Goods', 'डाउन गुड्स नाली की सफ़ाई', 'Blocked cess drain keeps ballast saturated (F1).', 'बंद नाली के कारण बैलास्ट भीगा रहता है (F1)।', 'If the drain runs clear and relay current is above 150 mA, the cause is not drainage.', 'यदि नाली साफ़ बहती है और रिले करंट 150 mA से ऊपर है, तो कारण जल निकासी नहीं है।', '2026-07-17'::date, '01:50'::time, '03:20'::time, 'warning'::alert_level, 'planned'::task_status) on conflict (id) do update set title = excluded.title, status = excluded.status;
insert into field_task (id, asset_id, block_window_id, title, title_hi, hypothesis, hypothesis_hi, falsifier, falsifier_hi, service_date, starts_at, ends_at, level, status) values ('task-16t', 'ADRA/TC/16T', 'RB-30', 'Check points for metallic bridging', 'पॉइंट्स पर धातु ब्रिजिंग की जाँच', 'Metal debris near the points is bridging the rails (F4).', 'पॉइंट्स के पास धातु का मलबा रेलों को जोड़ रहा है (F4)।', 'If no debris is found and ballast is dry, re-rank toward F1.', 'यदि कोई मलबा नहीं मिलता और बैलास्ट सूखा है, तो F1 की ओर पुनः क्रम दें।', '2026-07-18'::date, '02:00'::time, '03:30'::time, 'watch'::alert_level, 'planned'::task_status) on conflict (id) do update set title = excluded.title, status = excluded.status;
